314			UserID: &userID,
315			Key:    storepb.UserSetting_WEBHOOKS,
316		})
317		if err != nil {
318			return nil, err
319		}
320		if userSetting == nil {
321			return []*storepb.WebhooksUserSetting_Webhook{}, nil
322		}
323	
324		webhooksUserSetting := userSetting.GetWebhooks()
325		return webhooksUserSetting.Webhooks, nil
326	}
